using System;
using System.IO;
using Microsoft.AspNetCore.Hosting;

namespace QuickCode.Quickcode.Portal.Helpers.BlobStorage;

/// <summary>
/// Stores images under wwwroot/uploads for local/demo use.
/// </summary>
public sealed class LocalFileBlobImageStorage : IBlobImageStorage
{
    private readonly IWebHostEnvironment _environment;
    private readonly string _publicBaseUrl;

    public LocalFileBlobImageStorage(IWebHostEnvironment environment)
    {
        _environment = environment;
        _publicBaseUrl = (Environment.GetEnvironmentVariable("LOCAL_PUBLIC_BASE_URL") ?? "/uploads")
            .TrimEnd('/');
    }

    public string Upload(Stream content, string contentType)
    {
        var uploadsRoot = Path.Combine(_environment.WebRootPath ?? "wwwroot", "uploads");
        Directory.CreateDirectory(uploadsRoot);

        var fileName = $"{Guid.NewGuid()}.{GetExtension(contentType)}";
        var filePath = Path.Combine(uploadsRoot, fileName);

        if (content.CanSeek)
        {
            content.Position = 0;
        }

        using (var fileStream = File.Create(filePath))
        {
            content.CopyTo(fileStream);
        }

        return $"{_publicBaseUrl}/{fileName}";
    }

    private static string GetExtension(string contentType)
    {
        if (string.IsNullOrWhiteSpace(contentType))
        {
            return "bin";
        }

        var parts = contentType.Split('/');
        return parts.Length > 1 ? parts[^1] : "bin";
    }
}
